    x, y = observation.get('self_position', [0, 0])
    w = observation.get('grid_width', 10)
    h = observation.get('grid_height', 10)
    obstacles = set(map(tuple, observation.get('obstacles', [])))
    resources = list(map(tuple, observation.get('resources', [])))
    opp = observation.get('opponent_position', [])
    if len(opp) >= 2:
        ox, oy = opp[0], opp[1]
    else:
        ox, oy = x, y  # Default if no opponent info

    def safe(nx, ny):
        return 0 <= nx < w and 0 <= ny < h and (nx, ny) not in obstacles

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    # Move towards closest resource
    min_dist = None
    target_resource = None
    for r in resources:
        d = dist((x, y), r)
        if min_dist is None or d < min_dist:
            min_dist = d
            target_resource = r
    if target_resource:
        dx = (target_resource[0] > x) - (target_resource[0] < x)
        dy = (target_resource[1] > y) - (target_resource[1] < y)
        nx, ny = x + dx, y + dy
        if safe(nx, ny):
            return [dx, dy]

    # Pursue opponent
    dx = (ox > x) - (ox < x)
    dy = (oy > y) - (oy < y)
    nx, ny = x + dx, y + dy
    if safe(nx, ny):
        return [dx, dy]

    # Move to any safe neighbor
    for move_dx, move_dy in [ (1,0), (-1,0), (0,1), (0,-1) ]:
        nx, ny = x + move_dx, y + move_dy
        if safe(nx, ny):
            return [move_dx, move_dy]
    return [0, 0]

